INSERT IGNORE INTO newstart_empirical_cases
  (article_id, board_name, title, author_nickname, written_at, view_count, application_type, content_raw, source_url, collected_at, created_by, created_at, updated_at)
VALUES
  ('3438', '초보가이드', '10프로 추가감면 교육', NULL, '2026-01-05 21:13:00', 1, NULL, '[RAW capture — 원문 보존]\nSOURCE_COMMUNITY: NEWSTART_BORROWER_CAFE (clubId 31312978, newhopero)\nBOARD: 초보가이드\nARTICLE_ID: 3438\nTITLE: 10프로 추가감면 교육\nAUTHOR: 지피지기자산 (카페매니저)\nWRITTEN_AT: 2026.01.05. 21:13\nVIEWS: 1,137 | COMMENTS: 9 | LIKES: 18\nSOURCE_URL: https://cafe.naver.com/ArticleRead.nhn?clubid=31312978&articleid=3438\nCOLLECTED_AT: 2026-09-30 (Qoder browser-use, logged-in iframe)\nEXTRACTION_METHOD: innerText capture (full 2383자)\nSOURCE_TYPE: OPERATOR_KNOWLEDGE (지정수집)\n\n--- BEGIN BODY ---\n10프로 추가감면 교육은 폐업증명서가 있어야 가능합니다.\n없으신 분들은 사업자 등록증을 내어서 3개월 정도 이후에 폐업을 하여 받으십시오.\n\n가장 확실한 10프로 추가감면 받는 루트는\n1) 국민취업제도 + 희리패 재창업 (이러닝 + 비대면)\n2) 국민취업제도 + 희리패 재취업 (기초+심화)\n코스입니다.\n확정안 결정짓는 담당자들이 작년에 1번과 2번 이외 경우에는 높은 감면을 주지 않았다고 합니다.\n\n국민취업제도 정보입니다.\n2026년 국민취업지원제도는 취업을 원하는 분들에게 취업 지원 서비스와 함께 생계비를 지원하는 한국형 실업부조 제도입니다. 본인의 소득과 재산 수준에 따라 1유형과 2유형으로 나뉩니다.\n\n1. 유형별 자격 요건\n[1유형] 구직촉진수당 지급 — 저소득층의 생계와 취업을 동시에 돕는 유형입니다. (구직촉진수당: 월 60만원 × 6개월 + 부양가족 수당)\n[2유형] 취업활동비용 지원 — 1유형에 해당하지 않는 분들을 위한 맞춤형 취업 지원 유형입니다. (취업활동비용: 직업훈련 참여 시 최대 195.4만원 등 지원)\n특정계층: 결혼이민자, 북한이탈주민, 위기청소년, 영세 자영업자 등\n청년: 18~34세 구직자 (소득·재산 무관)\n중장년: 35~69세 구직자 중 가구원 합산 중위소득 100% 이하\n\n2. 신청 방법 및 절차\n신청은 온라인과 오프라인 모두 가능합니다. 신청 전 워크넷(고용24) 구직등록이 필수입니다.\n① 온라인 신청 (권장): 고용24(work24.go.kr) 접속 및 로그인 → 워크넷 구직등록 완료 (이력서 작성 및 구직 신청) → ''국민취업지원제도'' 메뉴에서 취업지원 신청서 작성 및 제출 → 가구원 개인정보 동의 등 온라인 절차 이행\n② 오프라인 신청: 거주지 관할 고용센터에 직접 방문하여 신청서 작성 및 상담\n③ 필요 서류: 대부분의 소득·재산 정보는 행정정보망을 통해 자동 확인되지만, 상황에 따라 다음 서류가 필요할 수 있습니다.\n가구원 확정 서류: 주민등록등본, 가족관계증명서\n소득·재산 증빙 서류: 전대차 계약서, 사업장 임대차 계약서 등 (자동 확인이 안 되는 경우)\n특정계층 증빙 서류: 관련 확인서(해당자만)\n\n3. 진행 절차 (프로세스)\n신청 및 접수: 고용센터 심사 (한 달 이내 수급자격 결정)\n취업활동계획(IAP) 수립: 고용센터 상담원과 3회 상담 (구직활동 계획 수립)\n구직활동 이행: 직업훈련, 면접 참여 등 계획된 활동 수행\n수당 지급: 매월 구직활동 보고서 제출 시 수당 지급\n취업성공수당: 취업 후 일정 기간 근속 시 최대 150만원 별도 지급\n--- END BODY ---\n\n--- COMMENTS (9) ---\n[1] 꼬부우기2 | 2026.01.05. 21:19 | "정말 최고에요ㅠㅠ 단톡방에서 정말 많은 도움 받고있습니다.. 알려주시는 정보도 전부 꿀정보!!!"\n[2] 최고이지 | 2026.01.06. 17:40 | "우아 세세한 정보 감사합니다!"\n[3] 시금치팡 | 2026.01.06. 20:01 | "꿀정보 와우 감사합니다"\n[4] 최고이지 | 2026.01.11. 23:10 | "현재 1유형 받고있는데 구직촉진수당: 월 50만원 × 6개월 ---> 60만원 * 6개월 주는걸로 바뀌었어요~" | REPEATED_OBSERVATION(제도 변경 회원 보고)\n[5] 새롭게 시작 | 2026.02.11. 14:14 | "이건 어떻게 받는건가요?"\n[6] 셋을위해 | 2026.02.12. 09:42 | "새롭게 시작 위글읽으시면 국민취업제도 1유형신청하셔서 해당되면 위글대로 프로세스하시고~~~~"\n[7] 시루봉 | 2026.02.25. 12:56 | "추가감면용 사업장도 거래,판매 등 영업 이력을 요구한다는 이야기가 있던데 혹시 아시는거있으실까요?" | COMMUNITY_OPINION(질문)\n[8] 디카프리5 | 2026.04.14. 14:34 | "안녕하세요 전 직장+사업 하다 폐업을 했습니다. 이럴경우 추가감면을 받을수 있는건 뭐가 있을까요?" | MEMBER_CASE(질문)\n[9] 지피지기자산 (운영자) | 2026.04.14. 14:38 | "추가감면 검색하시면 정보가ㅜ나오니 살펴보십시오" | COUNSELOR_CLAIM\n', 'https://cafe.naver.com/newhopero/3438', NOW(6), 'CASE_COLLECTOR_20260930', NOW(6), NOW(6));

