INSERT IGNORE INTO newstart_empirical_cases
  (article_id, board_name, title, author_nickname, written_at, view_count, application_type, content_raw, source_url, collected_at, created_by, created_at, updated_at)
VALUES
  ('6043', '질문게시판', '전자책구매', NULL, '2026-09-29 11:20:00', 10, NULL, '[RAW] SOURCE_COMMUNITY: NEWSTART_BORROWER_CAFE | BOARD: 질문게시판 | ARTICLE_ID: 6043\nTITLE: 전자책구매 | AUTHOR: 가을소나무 (감사멤버) | WRITTEN_AT: 2026.09.29. 11:20 | VIEWS:10 COMMENTS:3\nSOURCE_URL: https://cafe.naver.com/ArticleRead.nhn?clubid=31312978&articleid=6043\nCOLLECTED_AT: 2026-09-30 | METHOD: Qoder browser-use iframe innerText (full)\nSOURCE_TYPE: CAFE_QA — 운영자 절차안내 포함(원장초기화→장기연체확인→부실차주 신청 순서)\n\n--- BODY ---\n안녕하세요\n전자책 구매했습니다. 많은도움부탁드립니다\n--- END ---\n--- COMMENTS ---\n[1] 지피지기자산 (운영자) | 2026.09.29. 11:33 | COUNSELOR_CLAIM\n"전자책과 단톡방 정보를 이메일로 발송하였습니다. 아울러 새출발기금 신청절차도 메일 안에 적어드렸습니다."\n[2] 지피지기자산 (운영자) | 2026.09.29. 11:34 | COUNSELOR_CLAIM (절차 안내 — 운영 경험 기반, 공식 아님)\n"1. 우선 전자책을 보시면 원장초기화 관련에 가시면 새출발기금에 원장초기화 메일 보내는 글과 주소가 있으니 그 내용 그대로 새출발기금 주소로 이메일 보내세요. 이메일 보내고 3일 안에 보통 원장초기화 가 됩니다. 장기연체등록이 되고 원장초기화하라고 하지만 전자책 내용대로 보내면 바로 원장초기화 시켜줍니다.\n2. 3-7일 사이에 신용정보원에 가시면 장기연체등록이 되어있는지 확인하세요. 전자책에 보시면 신용정보원 사이트 주소와 확인 방법이 나옵니다.\n3. 장기연체등록이 확인되면 새출발기금 사이트에 가셔서 부실차주 신청하시거나 근처 캠코로 가셔서 신청하시면 됩니다."\n[3] 가을소나무 | 2026.09.29. 11:35 | "감사합니다"\n', 'https://cafe.naver.com/newhopero/6043', NOW(6), 'CASE_COLLECTOR_20260930', NOW(6), NOW(6));

