INSERT IGNORE INTO newstart_empirical_cases
  (article_id, board_name, title, author_nickname, written_at, view_count, application_type, content_raw, source_url, collected_at, created_by, created_at, updated_at)
VALUES
  ('6046', '질문게시판', '부실우려 신청 후', NULL, '2026-09-29 15:36:00', 15, NULL, '[RAW] SOURCE_COMMUNITY: NEWSTART_BORROWER_CAFE | BOARD: 질문게시판 | ARTICLE_ID: 6046\nTITLE: 부실우려 신청 후 | AUTHOR: 부족한형 (일반멤버) | WRITTEN_AT: 2026.09.29. 15:36 | VIEWS:15 COMMENTS:2\nSOURCE_URL: https://cafe.naver.com/ArticleRead.nhn?clubid=31312978&articleid=6046\nCOLLECTED_AT: 2026-09-30 | METHOD: Qoder browser-use iframe innerText (full)\nSOURCE_TYPE: CAFE_QA (부실우려→부실차주 전환 미납 전략 질문)\n\n--- BODY ---\n10월10일 부터 남입하라고 메세지를 받았는데\n미납하면 되는 걸까요?\n--- END ---\n--- COMMENTS ---\n[1] 지피지기자산 (운영자) | 2026.09.29. 21:27 | COUNSELOR_CLAIM + REPEATED_OBSERVATION\n"네. 부실우려로 진행하다가 부실차주로 넘어가신 분들 사례에서는 납입 시작일이 와도 납입하지 않고 미납을 이어갔습니다. 실제 사례도 부실우려 신청 → 합의서 체결 → 납입 미납 → 최종 실효 → 장기연체 등록 확인 → 부실차주 신청 순서로 진행됐습니다. 그래서 10월 10일부터 납입하라는 문자를 받으신 상황이라면, 부실우려를 유지하려는 게 아니라 실효 후 부실차주로 가시는 경우에는 기존 사례들은 미납하는 쪽으로 진행했습니다. 5회차 미납때 실효된다는 연락이 옵니다."\n[2] 부족한형 | 2026.09.30. 09:15 | MEMBER_CASE\n"답변 감사드립니다. 많이 쫄리지만 이겨내야죠"\n', 'https://cafe.naver.com/newhopero/6046', NOW(6), 'CASE_COLLECTOR_20260930', NOW(6), NOW(6));

