INSERT IGNORE INTO newstart_empirical_cases
  (article_id, board_name, title, author_nickname, written_at, view_count, application_type, content_raw, source_url, collected_at, created_by, created_at, updated_at)
VALUES
  ('6050', '질문게시판', '폐업 후 보증금은 어떻게 되나요?', NULL, '2026-09-29 19:45:00', 26, NULL, '[RAW capture — 원문 보존]\nSOURCE_COMMUNITY: NEWSTART_BORROWER_CAFE (clubId 31312978, newhopero)\nBOARD: 질문게시판\nARTICLE_ID: 6050\nTITLE: 폐업 후 보증금은 어떻게 되나요?\nAUTHOR: 으싸으싸아 (일반멤버)\nWRITTEN_AT: 2026.09.29. 19:45\nVIEWS: 26 | COMMENTS: 4 | LIKES: 0\nSOURCE_URL: https://cafe.naver.com/ArticleRead.nhn?clubid=31312978&articleid=6050\nCOLLECTED_AT: 2026-09-30 (Qoder browser-use, logged-in iframe)\nEXTRACTION_METHOD: innerText capture (full body + comments)\nSOURCE_TYPE: CAFE_QA / 회원 정보글 (대상채움)\n\n--- BEGIN BODY ---\n폐업 후 보증금 받은거 부실 차주 갈때 통장거래내역에서 문제 삼지 않나요?\n\n예전엔 잔고만 확인하고 거래 내역은 확인 안한다는 글이 많은데 7월부터 강화 된 후 어떻게 되는지 궁금합니다.\n--- END BODY ---\n\n--- COMMENTS ---\n[1] 지피지기자산 (운영자) | 2026.09.29. 21:23 | COUNSELOR_CLAIM\n"최근 사례를 보니, 폐업 후 보증금을 받은 것을 새출발기금에서 물어보고 사용처 소명을 요구한다고 합니다."\n\n[2] 으싸으싸아 (글쓴이) | 2026.09.29. 21:50 | MEMBER_CASE(질문)\n"폐업 후 새출발 신청해도 그런가요?"\n\n[3] 후추 (회원) | 2026.09.30. 07:55 | MEMBER_CASE\n"소명없습니다"\n\n[4] 지피지기자산 (운영자) | 2026.09.30. 08:21 | OPERATOR_OBSERVATION (중요: 운영 변화 감지 근거)\n"[2026년 8월 이후 부실차주 심사 변화 의심 사례]\n2024년 운영자 실제 사례: 2024년 6월 폐업 → 2024년 8월 20일경 부실차주 신청. 폐업사실증명 제출. 이미 폐업한 사업장의 상가임대차계약서 및 보증금 반환내역을 접수 후 별도로 요구받지 않음.\n과거 다른 차주 사례: 신청 전에 이미 폐업한 차주들에게서도 유사하게 폐업 사업장 보증금 반환자료를 접수 후 별도 요구하지 않은 사례가 있었음.\n2026년 8월 이후 관찰: 신청서를 먼저 접수한 뒤 심사 과정에서 차주에게 개별적으로 연락하여, 이미 폐업한 사업장의 기존 임대차서류 + 보증금 반환 관련 서류/반환 현황을 추가 요구하는 사례가 나타남."\n--- END COMMENTS ---\n', 'https://cafe.naver.com/newhopero/6050', NOW(6), 'CASE_COLLECTOR_20260930', NOW(6), NOW(6));

