INSERT IGNORE INTO newstart_empirical_cases
  (article_id, board_name, title, author_nickname, written_at, view_count, application_type, content_raw, source_url, collected_at, created_by, created_at, updated_at)
VALUES
  ('798001', '연체전(신속),이자율(프리),채무조정(개인) (menuId 87)', '[금융정책] 신복위에서 9월7일부터 심사시 금융자산을 보기 시작했습니다 (예적금, 개인연금, 보험, 주식 등)', NULL, '2026-09-24 13:13:00', 2961, 'B-CAFE(신복위회원카페)', '[RAW capture — 원문 보존]\nSOURCE_COMMUNITY: CCRS_CAFE (clubId 27453843, ccrs5500)\nBOARD: 연체전(신속),이자율(프리),채무조정(개인) (menuId 87)\nARTICLE_ID: 798001\nTITLE: [금융정책] 신복위에서 9월7일부터 심사시 금융자산을 보기 시작했습니다 (예적금, 개인연금, 보험, 주식 등)\nAUTHOR: 솔라리스 (인기멤버 / 일반회원 — 운영자 아님)\nWRITTEN_AT: 2026.09.24. 13:13\nVIEWS: 2961 | COMMENTS: 73 | LIKES: 38\nSOURCE_URL: https://cafe.naver.com/ccrs5500/798001\nCOLLECTED_AT: 2026-09-30 (Qoder browser-use, logged-in m.cafe search click)\nEXTRACTION_METHOD: innerText capture (full body + head comments)\nSOURCE_TYPE: CAFE_CASE / 회원 정보글 (운영 변화 관찰)\nSEARCH_KEYWORDS: [부실차주]  (ccrs5500 키워드검색 최신순, 9/24 창)\nOPERATIONAL_STATE: OFFICIAL_CHANGE_UNCONFIRMED (회원 글이 신복위·금융위 공식 공지 링크를 인용; FACT 승격 금지, REVIEW 유지)\n\n--- BEGIN BODY ---\n신복위 홈페이지 공지사항 및 카페내 스텝분 관련 답변글로 확인시\n26년 9월 7일 부터 금융마이데이터를 활용해 기존 재산(부동산, 자동차, 전월세 보증금) 외 신청자의 금융자산을 추가 들여다 보는 것으로 심사정책이 변경되었다고 합니다.\n\n☞ 최근 새출발기금 부실차주에서 신청자 재산/소득을 면밀히 보지 않고 최소감면율 60%를 적용한 것에 대해 감사원 지적이 있은 이후, 신청자의 금융자산을 보는 것으로 관련 제도 및 시스템이 보완되었으며 금번 신복위 심사정책 변화도 그 연장선상에 있다고 보여집니다.\n[인용 링크] 금융위원회 www.fsc.go.kr/no010101/86770 — "더욱 꼼꼼한 상환능력 심사를 통해 도덕적 해이 없는 채무조정을 지원하겠습니다" (신용정보법 개정안 국회 본회의 통과 ''26.4.23): 새도약기금·새출발기금 등 정부 채무조정 기구의 상환능력 심사 시 채무자의 금융자산·가상자산 보유내역까지 추가 확인.\n\n☞ 금융마이데이터 연동을 통한 신복위 채무조정 신청인 금융자산 조회 시행 (9/7부)\n(시범운영) 26.8.31 ~ 26.9.4 (신복위 서울중앙지부)\n(정식시행) 26.9.7 (전 지부)\n(조회항목)\n① 은행업권(예금, 적금, 펀드, 신탁/ISA 등)\n② 보험업권(보험 등)\n③ 금융투자업권(예수금, 주식, 파생상품 등)\n④ 휴면예금･보험\n(반영정책) 구체적인 세부 운영기준은 확인되지 않음.\n[인용 링크] 신복위 www.ccrs.or.kr 공지 — 조회 결과에 따라 추가 서류 제출이 필요할 수 있음. 시범 26.8.31~9.4 서울중앙지부, 정식 26.9.7 전 지부.\n\n☞ (9/25 업데이트) 워크아웃 상담 시 3,500만원 초과 시 접수불가로 안내받으셨다는 제보, 2,000만원 초과 시 불가로 안내받은 분도 계심. 추정: 기존 재산(부동산,보증금,자동차)+금융자산이 총채무를 넘지 않는 조건으로 심사(단 확실치 않음).\n☞ (9/25 업데이트) 신복위 스텝 댓글을 보니 채무과중도에 포함하여 감면율 산정에 반영하는 것으로 추정.\n\n#신용회복위원회 #금융자산 #예적금 #주식 #코인 #연금저축 #재산 #마이데이터 #보험\n--- END BODY ---\n\n--- COMMENTS (head, 73 중 일부) ---\n[1] 동글이83 | 2026.09.24. 13:17 | MEMBER_CASE(질문)\n"9월 신청자부터 해당되는거죠? 8월28일 신청했는데 재산 조회해도 재산이 없지만 7월말에 지인에게 300만원 빌린게 통장에 있어서"\n[2] 솔라리스(작성자) | 2026.09.24. 13:19 | MEMBER_CASE\n"네, 그리고 그 정도 금액은 있어도 큰 영향이 없을 것으로 보입니다"\n--- END COMMENTS ---\n', 'https://cafe.naver.com/ArticleRead.nhn?clubid=27453843&articleid=798001', NOW(6), 'CASE_COLLECTOR_20260930', NOW(6), NOW(6));

